import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

// Story F4 — Modal, checked in the source.
//
// The Modal paints only through the redesign's tokens: no literal colors,
// none of the old color or type tokens, and the new modal radius. Its
// footer helper renders confirm before cancel and leaves layout to the
// Modal's footer row. The modal radius is a single token in @theme. The
// rendered look is checked in the browser by e2e/modal-design.spec.ts.
// Do not edit this file to match an implementation.

const SRC = fileURLToPath(new URL('../../', import.meta.url));

function source(path: string) {
  return readFileSync(join(SRC, path), 'utf8');
}

function withoutComments(code: string) {
  return code.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
}

const OLD_COLOR_TOKENS = [
  'background',
  'foreground',
  'ink-2',
  'ink-3',
  'rule',
  'rule-strong',
  'hover-tint',
  'panel-tint',
  'accent',
  'accent-hover',
  'ok-tint',
  'required',
  'recommended',
  'incomplete',
];

describe('F4 Modal source', () => {
  it('uses only the new tokens', () => {
    const code = withoutComments(source('components/ui/Modal.tsx'));

    expect(code).not.toMatch(/#[0-9a-f]{3,8}\b/i);
    expect(code).not.toMatch(/\b(rgb|rgba|hsl|hsla|oklch)\(/);
    expect(code).not.toMatch(/\b(text|bg|border)-(white|black)\b/);
    for (const name of OLD_COLOR_TOKENS) {
      expect(code, `old token ${name}`).not.toMatch(
        new RegExp(`\\b(text|bg|border|outline|ring|fill|stroke)-${name}(?![\\w-])`)
      );
    }
    expect(code).not.toMatch(/\bfont-display\b/);
    expect(code).not.toMatch(/\btext-(headline|body|help)\b(?!-)/);
    expect(code).not.toMatch(/\brounded-(\[|sm\b|md\b|lg\b|btn\b)/);
    expect(code).not.toMatch(/\[font-weight:/);

    for (const utility of [
      'rounded-modal',
      'bg-modal-background',
      'border-modal-background',
      'bg-modal-title-background',
      'bg-modal-backdrop',
      'text-title-3',
    ]) {
      expect(code, utility).toMatch(new RegExp(`\\b${utility}\\b`));
    }
  });

  it('ModalActions renders confirm before cancel, with no layout of its own', () => {
    const code = withoutComments(source('components/ui/ModalActions.tsx'));
    const confirm = code.indexOf('data-testid={confirmTestId}');
    const cancel = code.indexOf('data-testid={cancelTestId}');
    expect(confirm).toBeGreaterThan(-1);
    expect(cancel).toBeGreaterThan(-1);
    expect(confirm, 'confirm first').toBeLessThan(cancel);
    expect(code).not.toMatch(/className=/);
  });

  it('declares --radius-modal once, inside @theme, as 10px', () => {
    const css = source('app/globals.css');
    const declarations = css.match(/--radius-modal\s*:[^;]*;/g) ?? [];
    expect(declarations).toHaveLength(1);
    expect(declarations[0]).toMatch(/--radius-modal\s*:\s*10px\s*;/);

    const themeBlocks = css.match(/@theme[^{]*\{[^}]*\}/g) ?? [];
    expect(themeBlocks.some((block) => /--radius-modal\s*:\s*10px\s*;/.test(block))).toBe(true);
  });
});
